class Solution:
    def getFolderNames(self, names: List[str]) -> List[str]:
        used = set()
        ans = []
        for name in names:
            if name not in used:
                used.add(name)
                ans.append(name)
            else:
                k = 1
                while f"{name}({k})" in used:
                    k += 1
                cand = f"{name}({k})"
                used.add(cand)
                ans.append(cand)
        return ans

