public:
    vector<string> getFolderNames(vector<string>& names) {
        unordered_set<string> used;
        unordered_map<string, int> nxt;
        vector<string> ans;
        for (auto& name : names) {
            if (!used.count(name)) {
                used.insert(name);
                ans.push_back(name);
            } else {
                int k = nxt.count(name) ? nxt[name] : 1;
                string cand;
                while (true) {
                    cand = name + "(" + to_string(k) + ")";
                    if (!used.count(cand)) break;
                    k++;
                }
                used.insert(cand);
                nxt[name] = k + 1;
                ans.push_back(cand);
            }
        }
        return ans;
    }
};

