class Solution {
    public String[] getFolderNames(String[] names) {
        Set<String> used = new HashSet<>();
        Map<String, Integer> nxt = new HashMap<>();
        String[] ans = new String[names.length];
        for (int i = 0; i < names.length; i++) {
            String name = names[i];
            if (!used.contains(name)) {
                used.add(name);
                ans[i] = name;
            } else {
                int k = nxt.getOrDefault(name, 1);
                String cand;
                while (true) {
                    cand = name + "(" + k + ")";
                    if (!used.contains(cand)) break;
                    k++;
                }
                used.add(cand);
                nxt.put(name, k + 1);
                ans[i] = cand;
            }
        }
        return ans;
    }
}

